import type { TripType } from './data'

export type AffiliateCategory = TripType | 'transfers'

export type AffiliatePartner = {
  id: string
  name: string
  category: AffiliateCategory
  url: string
  status: 'verified' | 'unverified'
}

/** Klook hotel affiliate handoff generated by Travelpayouts with the owner's aid parameter. */
export const KLOOK_HOTELS_AFFILIATE_URL = 'https://klook.tpx.lv/LvAH7l4w'

/** Trip.com direct affiliate short link supplied by the account owner (Alliance ID 11493329). */
export const TRIP_HOTELS_AFFILIATE_URL = 'https://www.trip.com/t/SsY6ZaegIX2'

/** Affiliate tracking marker supplied by the account owner. */
export const AFFILIATE_MARKER_ID = '806576'
export const AFFILIATE_IDS = { aviasales: AFFILIATE_MARKER_ID } as const

/**
 * Exact generated Travelpayouts short links. 'verified' means the Link API
 * returned success and the URL matched the provider-specific HTTPS short host.
 * No synthetic click is made to test redirects or inflate partner click metrics.
 */
export const AFFILIATE_PARTNERS: Record<AffiliateCategory, AffiliatePartner[]> = {
  flights: [
    { id: 'aviasales', name: 'Aviasales', category: 'flights', url: 'https://aviasales.tpx.lv/ZOqzJHaf', status: 'verified' },
  ],
  hotels: [
    { id: 'trip-hotels', name: 'Trip.com', category: 'hotels', url: TRIP_HOTELS_AFFILIATE_URL, status: 'unverified' },
    { id: 'klook-hotels', name: 'Klook Hotels', category: 'hotels', url: 'https://klook.tpx.lv/LvAH7l4w', status: 'verified' },
    { id: 'kkday', name: 'KKday Package Tours', category: 'hotels', url: 'https://kkday.tpx.lv/x5gqHfDJ', status: 'verified' },
  ],
  cars: [
    { id: 'autoeurope', name: 'AutoEurope', category: 'cars', url: 'https://autoeurope.tpx.lv/1NuZscel', status: 'verified' },
    { id: 'qeeq', name: 'QEEQ Global Car Rental', category: 'cars', url: 'https://qeeq.tpx.lv/n9oGqafJ', status: 'verified' },
  ],
  tours: [
    { id: 'tiqets', name: 'Tiqets', category: 'tours', url: 'https://tiqets.tpx.lv/sSYehXWU', status: 'verified' },
  ],
  transfers: [
    { id: 'kiwitaxi', name: 'Kiwitaxi', category: 'transfers', url: 'https://kiwitaxi.tpx.lv/wN8KUFkg', status: 'verified' },
    { id: 'gettransfer', name: 'GetTransfer.com', category: 'transfers', url: 'https://gettransfer.tpx.lv/yYXGNhMm', status: 'verified' },
    { id: 'intui', name: 'Intui.travel', category: 'transfers', url: 'https://intui.tpx.lv/6QOOPhJd', status: 'verified' },
  ],
}

export function getAffiliatePartners(category: AffiliateCategory): AffiliatePartner[] {
  return AFFILIATE_PARTNERS[category].filter(partner => partner.status === 'verified')
}

export function isVerifiedAffiliateUrl(value: string): boolean {
  return Object.values(AFFILIATE_PARTNERS).some(partners =>
    partners.some(partner => partner.status === 'verified' && partner.url === value),
  )
}

export function findVerifiedAffiliatePartner(value: string): AffiliatePartner | null {
  for (const partners of Object.values(AFFILIATE_PARTNERS)) {
    const partner = partners.find(item => item.status === 'verified' && item.url === value)
    if (partner) return partner
  }
  return null
}

/** Return a verified generated short link for a category/provider slot. */
export function buildAffiliateUrl(category: AffiliateCategory, partnerIndex = 0): string {
  const partners = getAffiliatePartners(category)
  if (!partners.length) return ''
  return partners[partnerIndex % partners.length].url
}
